/// A verb form: which cell of its conjugation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// A finite verb: a tense, its copula, the subject.
    Finite(
        crate::Polarity,
        crate::Ability,
        crate::Tense,
        crate::Copula,
        crate::Subject,
    ),
    /// The past (`-DI`), with its copula.
    Past(
        crate::Polarity,
        crate::Ability,
        crate::PastCopula,
        crate::Subject,
    ),
    /// The conditional (`-sA`), with its copula.
    Conditional(
        crate::Polarity,
        crate::Ability,
        crate::MoodCopula,
        crate::Subject,
    ),
    /// The optative (`-(y)A`), with its copula.
    Optative(
        crate::Polarity,
        crate::Ability,
        crate::MoodCopula,
        crate::Subject,
    ),
    /// An imperative.
    Imperative(crate::Polarity, crate::Ability, crate::Addressee),
    /// The infinitive (`-mAk`).
    Infinitive(crate::Polarity, crate::Ability),
    /// The verbal noun (`-mA`).
    AlNoun(crate::Polarity, crate::Ability),
    /// A subject participle.
    Participle(crate::Polarity, crate::Ability, crate::Participle),
    /// An object participle, with its subject's possessive.
    Relative(
        crate::Polarity,
        crate::Ability,
        crate::Relative,
        crate::Subject,
    ),
    /// A converb.
    Converb(crate::Polarity, crate::Ability, crate::Converb),
}

impl Cell {
    /// Its place in a paradigm: its group's first cell, then its values
    /// counted in order, the last fastest.
    pub const fn index(self) -> usize {
        match self {
            Cell::Finite(polarity, ability, tense, copula, subject) => {
                cell::POS_PLAIN_AOR___1SG as usize
                    + (((polarity as usize * 2 + ability as usize) * 6 + tense as usize) * 4
                        + copula as usize)
                        * 6
                    + subject as usize
            }
            Cell::Past(polarity, ability, past_copula, subject) => {
                cell::PAST_POS_PLAIN___1SG as usize
                    + ((polarity as usize * 2 + ability as usize) * 3 + past_copula as usize) * 6
                    + subject as usize
            }
            Cell::Conditional(polarity, ability, mood_copula, subject) => {
                cell::CONDITIONAL_POS_PLAIN___1SG as usize
                    + ((polarity as usize * 2 + ability as usize) * 3 + mood_copula as usize) * 6
                    + subject as usize
            }
            Cell::Optative(polarity, ability, mood_copula, subject) => {
                cell::OPTATIVE_POS_PLAIN___1SG as usize
                    + ((polarity as usize * 2 + ability as usize) * 3 + mood_copula as usize) * 6
                    + subject as usize
            }
            Cell::Imperative(polarity, ability, addressee) => {
                cell::IMPERATIVE_POS_PLAIN_2SG as usize
                    + (polarity as usize * 2 + ability as usize) * 8
                    + addressee as usize
            }
            Cell::Infinitive(polarity, ability) => {
                cell::INFINITIVE_POS_PLAIN as usize + polarity as usize * 2 + ability as usize
            }
            Cell::AlNoun(polarity, ability) => {
                cell::VERBAL_NOUN_POS_PLAIN as usize + polarity as usize * 2 + ability as usize
            }
            Cell::Participle(polarity, ability, participle) => {
                cell::PARTICIPLE_POS_PLAIN_AN as usize
                    + (polarity as usize * 2 + ability as usize) * 3
                    + participle as usize
            }
            Cell::Relative(polarity, ability, relative, subject) => {
                cell::RELATIVE_POS_PLAIN_DIK_1SG as usize
                    + ((polarity as usize * 2 + ability as usize) * 2 + relative as usize) * 6
                    + subject as usize
            }
            Cell::Converb(polarity, ability, converb) => {
                cell::CONVERB_POS_PLAIN_KEN as usize
                    + (polarity as usize * 2 + ability as usize) * 9
                    + converb as usize
            }
        }
    }
}

